<script>
import { Form, Head, Link } from '@inertiajs/vue3';
import InputError from '@scaffold/components/InputError.vue';
import PrimaryButton from '@scaffold/components/PrimaryButton.vue';
import { login } from '@app/routes';
import { request, update } from '@app/routes/password';

export default {
    name: 'ResetPassword',
    components: { Form, Head, InputError, Link, PrimaryButton },
    props: {
        email: String,
        token: String,
        passwordRules: String,
    },
    data() {
        return {
            resetPasswordForm: update.form(),
            requestLinkUrl: request.url(),
            loginUrl: login.url(),
        };
    },
};
</script>

<template>
    <div>
        <Head title="Atjaunot paroli" />
        <div class="row justify-content-center">
            <div class="lg:col-4 md:col-6 sm:col-8 ms-auto me-auto">
                <div class="card">
                    <div class="card-header card-header-primary text-center">
                        <h1 class="card-title h4">Atjaunot paroli</h1>
                    </div>
                    <Form v-bind="resetPasswordForm" :reset-on-success="['password', 'password_confirmation']" :reset-on-error="['password', 'password_confirmation']" v-slot="{ errors, processing }">
                        <div class="card-body">
                            <p>Ievadiet un apstipriniet jauno paroli.</p>
                            <input name="token" type="hidden" :value="token">
                            <InputError :message="errors.token" />
                            <div class="form-group">
                                <label for="reset-email">E-pasta adrese</label>
                                <input id="reset-email" name="email" type="email" class="form-control" :value="email" autocomplete="email" required readonly :aria-invalid="Boolean(errors.email)" :aria-describedby="errors.email ? 'reset-email-error' : undefined">
                                <InputError id="reset-email-error" :message="errors.email" />
                            </div>
                            <div class="form-group">
                                <label for="reset-password">Jaunā parole</label>
                                <input id="reset-password" name="password" type="password" class="form-control" autocomplete="new-password" :passwordrules="passwordRules" required autofocus :aria-invalid="Boolean(errors.password)" :aria-describedby="errors.password ? 'reset-password-error' : undefined">
                                <InputError id="reset-password-error" :message="errors.password" />
                            </div>
                            <div class="form-group">
                                <label for="reset-password-confirmation">Apstiprināt jauno paroli</label>
                                <input id="reset-password-confirmation" name="password_confirmation" type="password" class="form-control" autocomplete="new-password" :passwordrules="passwordRules" required :aria-invalid="Boolean(errors.password_confirmation)" :aria-describedby="errors.password_confirmation ? 'reset-password-confirmation-error' : undefined">
                                <InputError id="reset-password-confirmation-error" :message="errors.password_confirmation" />
                            </div>
                        </div>
                        <div class="card-footer justify-content-center">
                            <PrimaryButton type="submit" class="btn btn-primary" :disabled="processing">
                                {{ processing ? 'Saglabā…' : 'Saglabāt jauno paroli' }}
                            </PrimaryButton>
                        </div>
                    </Form>
                    <p class="text-center mb-2"><Link :href="requestLinkUrl">Pieprasīt jaunu atjaunošanas saiti</Link></p>
                    <p class="text-center mb-3"><Link :href="loginUrl">Atgriezties pie pieteikšanās</Link></p>
                </div>
            </div>
        </div>
    </div>
</template>
